                    nyckel = (c.raddr.ip, c.raddr.port, c.laddr.port)
                    if nyckel not in sedda:
                        sedda.add(nyckel)
                        logg.append({
                            "timestamp": datetime.now().isoformat(),
                            "kalla": f"{c.raddr.ip}:{c.raddr.port}",
                            "dest_port": c.laddr.port,
                        })
            time.sleep(interval_s)
    except KeyboardInterrupt:
        return logg
