import os
import stat

def audit_file_permissions(directory: str) -> list[dict]:
    issues = []
    for root, _, files in os.walk(directory):
        for name in files:
            path = os.path.join(root, name)
            try:
                mode = os.stat(path).st_mode
            except OSError:
                continue
            problems = []
            if mode & stat.S_IWOTH:
                problems.append("world-writable")
            if mode & stat.S_IROTH and mode & stat.S_IXOTH:
                problems.append("world-readable-executable")
            if mode & stat.S_ISUID and mode & stat.S_IXUSR:
                problems.append("setuid")
            if problems:
                issues.append({
                    "path": path,
                    "mode": oct(stat.S_IMODE(mode)),
                    "issues": problems,
                })
    return issues
