import math
from collections import Counter
from scapy.all import rdpcap, DNS, DNSQR

def analyze_dns_traffic(pcap_file: str) -> dict:
    def entropy(s: str) -> float:
        c = Counter(s)
        return -sum((n/len(s)) * math.log2(n/len(s)) for n in c.values()) if s else 0

    queries = []
    for pkt in rdpcap(pcap_file):
        if pkt.haslayer(DNS) and pkt.haslayer(DNSQR) and pkt[DNS].qr == 0:
            queries.append(pkt[DNSQR].qname.decode(errors="ignore").rstrip("."))

    suspicious = {"dga": [], "tunneling": [], "exfiltration": []}
    subdomain_count = Counter()

    for domain in set(queries):
        labels = domain.split(".")
        name = labels[0]
        # DGA: hög entropi + långt label utan vokaler-mönster
        if len(name) > 12 and entropy(name) > 3.5:
            suspicious["dga"].append(domain)
        # Tunneling: mycket långa queries
        if len(domain) > 100 or any(len(l) > 52 for l in labels):
            suspicious["tunneling"].append(domain)
        # Exfiltration: många unika subdomäner under samma bas
        if len(labels) > 2:
            subdomain_count[".".join(labels[-2:])] += 1

    suspicious["exfiltration"] = [b for b, n in subdomain_count.items() if n > 20]
    return {"total_queries": len(queries), "suspicious": suspicious}
