def harden_ssh_config(config_path: str) -> dict:
    recommendations = {}
    settings = {}

    with open(config_path) as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split(None, 1)
            if len(parts) == 2:
                settings[parts[0].lower()] = parts[1].strip()

    checks = {
        "permitrootlogin": ("no", "Inaktivera root-inloggning"),
        "passwordauthentication": ("no", "Använd nyckelbaserad autentisering"),
        "permitemptypasswords": ("no", "Tillåt inte tomma lösenord"),
        "x11forwarding": ("no", "Inaktivera X11-forwarding"),
        "maxauthtries": ("3", "Begränsa antal inloggningsförsök"),
        "protocol": ("2", "Använd endast SSH protokoll 2"),
        "ignorerhosts": ("yes", "Ignorera rhosts-filer"),
        "hostbasedauthentication": ("no", "Inaktivera hostbaserad autentisering"),
        "logingracetime": ("30", "Kortare tidsgräns för inloggning"),
        "allowtcpforwarding": ("no", "Inaktivera TCP-forwarding om ej nödvändigt"),
    }

    for key, (safe_value, reason) in checks.items():
        current = settings.get(key)
        if current is None or current.lower() != safe_value.lower():
            recommendations[key] = {
                "current": current or "ej satt",
                "recommended": safe_value,
                "reason": reason,
            }

    return recommendations
